/// <summary> Конструктор класса </summary>
public void new()
{
    super();

    apiClient = new RMarketApiClientBybit();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::POST);
    apiClient.parmMethodUrl('/v5/spot-margin-trade/set-leverage');

    requestContract = new RMarketJson_Bybit_SetLeverage_Request();

    // Do this before execute()
    //apiClient.setBaseUrl(URL _baseUrl);
    //apiClient.setApiKey(RMarketApiKey _apiKey)
}

/// <summary> Отменить ордер на Bybit </summary>
/// <param name="_symbol"> Торговый символ </param>
/// <param name="_orderId"> ID ордера </param>
/// <returns> Результат удаления ордера </returns>
public void initParameters(int _leverage)
{
    //https://bybit-exchange.github.io/docs/v5/spot-margin-uta/set-leverage
    //leverage	true	string	Leverage. [2, 10].
    if (_leverage < 2 || _leverage > 10)
        throw error("Leverage must be in the range [2 .. 10]");

    requestContract.parmLeverage(int2Str(_leverage));
}

public void processResponse()
{
    super();

    str responseStr = apiClient.getResponseBody();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
        throw Error(strfmt("Request returns error!"));

    responseContract = RMarketJsonSerializer::deserializeObject(
        classNum(RMarketJson_Bybit_Response),
        responseStr) as RMarketJson_Bybit_Response;
}
